import sys

data = sys.stdin.read().split()
n = int(data[0])
a = list(map(int, data[1:1 + n]))
def dmax(v):
    m = 0
    while v:
        if v % 10 > m:
            m = v % 10
        v //= 10
    return m
r = 0
for x in a:
    if dmax(x) % 2 != 0:
        r ^= x
print(r)

